from PIL import Image, ImageDraw, ImageOps
im=Image.open('/app/pantomograph.jpg').convert('L')
def crop(box,name,s=2):
    c=im.crop(box); c=ImageOps.autocontrast(c,cutoff=1).resize(((box[2]-box[0])*s,(box[3]-box[1])*s)).convert('RGB')
    d=ImageDraw.Draw(c)
    for x in range((box[0]//50+1)*50,box[2],50):
        X=(x-box[0])*s; d.line([(X,0),(X,c.size[1])],fill=(255,0,0) if x%100==0 else (90,0,0))
        if x%100==0: d.text((X+2,2),str(x),fill=(255,255,0))
    for y in range((box[1]//50+1)*50,box[3],50):
        Y=(y-box[1])*s; d.line([(0,Y),(c.size[0],Y)],fill=(0,255,0) if y%100==0 else (0,90,0))
        if y%100==0: d.text((2,Y+2),str(y),fill=(255,255,0))
    c.save(name)
crop((720,600,1450,1100),'lr.png',2)
crop((1350,600,2150,1100),'ll.png',2)
crop((720,400,1450,800),'ur.png',2)
crop((1350,400,2150,800),'ul.png',2)
"", "description": "Make zoomed quadrant crops with grid"}

